-- Nickimart Medical — tenders, customer purchase orders and sourcing.
--
-- Purely additive. Twelve new tables, three new columns on existing ones (all
-- nullable or defaulted), and no DROP, no ALTER COLUMN, no TRUNCATE anywhere.
-- Generated by diffing the previous schema against the new one rather than
-- against a live database: diffing against a database makes the migration
-- describe *that* database, and the first attempt produced a DROP of the
-- migration runner's own `_NikiMigration` bookkeeping table because it is not
-- in the Prisma schema. A schema-to-schema diff cannot see stray tables and
-- therefore cannot propose removing them.
--
-- Re-runnable, like 0001: tables and indexes carry IF NOT EXISTS, columns are
-- added inside a DO block that swallows a duplicate, and each foreign key is
-- attempted inside a block that swallows a duplicate and nothing else.
--
-- Applied against MEDICAL_DATABASE_URL only. Touches no retail or
-- data-bundle table.

-- AlterTable. Every column is nullable or defaulted, so each of these is safe
-- against a table that already holds rows. IF NOT EXISTS on each one, so the
-- file can be re-run: a migration that is applied once by the runner and then
-- by hand during an incident should not fail the second time.
ALTER TABLE "medical_supplier_quotes"
  ADD COLUMN IF NOT EXISTS "sourcingRequestId" TEXT;

ALTER TABLE "medical_purchase_order_items"
  ADD COLUMN IF NOT EXISTS "salesOrderItemId" TEXT,
  ADD COLUMN IF NOT EXISTS "sourcingRequestItemId" TEXT;

ALTER TABLE "medical_supplier_invoices"
  ADD COLUMN IF NOT EXISTS "discrepancyKind" TEXT NOT NULL DEFAULT 'NONE',
  ADD COLUMN IF NOT EXISTS "isMatched" BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS "matchedAt" TIMESTAMP(3),
  ADD COLUMN IF NOT EXISTS "matchedById" TEXT NOT NULL DEFAULT '';

