-- ---------------------------------------------------------------------------
-- Duplicate supplier invoices
-- ---------------------------------------------------------------------------
-- The same invoice keyed twice is paid twice. The natural key is the supplier
-- plus their own invoice number, but that number is blank on an invoice we
-- have raised ourselves from a delivery note, and blanks are not duplicates of
-- each other — so a plain unique constraint would refuse the second such
-- record.
--
-- A partial unique index is the exact tool: uniqueness enforced only where the
-- supplier actually gave us a number. Prisma cannot express this, so it lives
-- here and surfaces as P2002 in application code; src/lib/medical/procurement
-- catches it and says which invoice it collided with.
CREATE UNIQUE INDEX IF NOT EXISTS "medical_supplier_invoices_supplier_ref_key"
  ON "medical_supplier_invoices" ("supplierId", "supplierReference")
  WHERE "supplierReference" <> '';

-- An approved-register row is drawn down by orders placed against it, so it is
-- read by (institution, product) on every quotation to that institution. The
-- index on (organisationId, status) alone makes that a scan of every award the
-- hospital ever gave us.
CREATE INDEX IF NOT EXISTS "medical_approved_products_org_product_valid_idx"
  ON "medical_approved_products" ("organisationId", "productId", "validUntil");
